theorem lg_target (a : ℤ) : a ^ 2 % 4 = 0 ∨ a ^ 2 % 4 = 1 := by
  cases a with n;
  constructor;
  · simp [pow, mod_eq_mod_of_divisible];
    rw [mod_eq_mod_of_divisible (div_two_mul_two_eq_self (n + 1))];
    simp [pow, mod_eq_mod_of_divisible];
  · simp [pow, mod_eq_mod_of_divisible];
    rw [mod_eq_mod_of_divisible (div_two_mul_two_eq_self n)];
    simp [pow, mod_eq_mod_of_divisible];
```
